diff --git a/repro/no-lonely-if-19033.js b/repro/no-lonely-if-19033.js
new file mode 100644
index 0000000..6d58655
--- /dev/null
+++ b/repro/no-lonely-if-19033.js
@@ -0,0 +1,25 @@
+"use strict";
+// Repro for no-lonely-if unsafe fix inside a brace-less outer `if`.
+// Usage: node repro/no-lonely-if-19033.js [path/to/other/eslint/lib/api]
+const path = require("node:path");
+const vm = require("node:vm");
+const code = require("node:fs").readFileSync(path.join(__dirname, "no-lonely-if.js"), "utf8");
+
+function check(label, apiPath) {
+    const { Linter } = require(apiPath);
+    const linter = new Linter({ configType: "flat" });
+    const messages = linter.verify(code, [], "x.js");
+    const { output, fixed } = linter.verifyAndFix(code, [], "x.js");
+    const run = src => { try { vm.runInNewContext(src, { Error }); return "ok"; } catch (e) { return `throws: ${e.message}`; } };
+    console.log(`== ${label} (eslint ${Linter.version})`);
+    console.log("messages:", messages.map(m => `${m.line}:${m.column} ${m.ruleId}: ${m.message}`));
+    console.log("fixed:", fixed);
+    if (fixed) console.log(output);
+    console.log("original runs:", run(code), "| fixed output runs:", run(output));
+    return fixed && run(code) !== run(output);
+}
+
+const broken = [check("checkout", path.join(__dirname, "../lib/api"))];
+if (process.argv[2]) broken.push(check("other", path.resolve(process.argv[2])));
+console.log(broken.some(Boolean) ? "BUG: autofix changed runtime behavior" : "no unsafe fix");
+process.exitCode = broken[0] ? 1 : 0;
diff --git a/repro/no-lonely-if.js b/repro/no-lonely-if.js
new file mode 100644
index 0000000..244c698
--- /dev/null
+++ b/repro/no-lonely-if.js
@@ -0,0 +1,6 @@
+/* eslint no-lonely-if: "error" */
+if (true)
+	if (false) {}
+	else { if (false) {} }
+	//     ^ Unexpected if as the only statement in an else block.
+else throw Error('This `else` should have been unreachable!');
